def verschluesseln(text, schluessel):
    ergebnis = ""
    for z in text:
        if "A" <= z <= "Z":
            ergebnis += chr((ord(z) - ord("A") + schluessel) % 26 + ord("A"))
        elif "a" <= z <= "z":
            ergebnis += chr((ord(z) - ord("a") + schluessel) % 26 + ord("a"))
        else:
            ergebnis += z
    return ergebnis


