import math


class Form:
    def flaeche(self):
        return 0


class Kreis(Form):
    def __init__(self, r):
        self.r = r

    def flaeche(self):
        return math.pi * self.r * self.r


class Rechteck(Form):
    def __init__(self, b, h):
        self.b = b
        self.h = h

    def flaeche(self):
        return self.b * self.h


n = int(input())
formen = []
for i in range(n):
    teile = input().split()
    if teile[0] == "kreis":
        formen.append(Kreis(float(teile[1])))
    else:
        formen.append(Rechteck(float(teile[1]), float(teile[2])))

gesamt = 0
for f in formen:
    print(f"{type(f).__name__}: {f.flaeche():.2f}")
    gesamt += f.flaeche()
print(f"Gesamt: {gesamt:.2f}")

def collatz(n):
    yield n
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        yield n


n = int(input())
