challenges.solution:
class KontoFehler(Exception):
    pass


class Bankkonto:
    def __init__(self):
        self._kontostand = 0

    @property
    def kontostand(self):
        return self._kontostand

    def einzahlen(self, betrag):
        if betrag <= 0:
            raise KontoFehler("Betrag muss positiv sein")
        self._kontostand += betrag

    def abheben(self, betrag):
        if betrag <= 0:
            raise KontoFehler("Betrag muss positiv sein")
        if betrag > self._kontostand:
            raise KontoFehler("Nicht genug Guthaben")
        self._kontostand -= betrag


konto = Bankkonto()
while True:
    teile = input().split()
    if teile[0] == "ende":
        break
    try:
        if teile[0] == "einzahlen":
            konto.einzahlen(int(teile[1]))
        elif teile[0] == "abheben":
            konto.abheben(int(teile[1]))
        elif teile[0] == "stand":
            print(f"Kontostand: {konto.kontostand} EUR")
        else:
            print("Unbekannter Befehl")
    except KontoFehler as e:
        print(f"Fehler: {e}")

