def zaehle_aufrufe(funktion):
    def wrapper(*args):
        wrapper.aufrufe += 1
        argumente = ", ".join(repr(a) for a in args)
        print(f"Aufruf {wrapper.aufrufe}: {funktion.__name__}({argumente})")
        return funktion(*args)
    wrapper.aufrufe = 0
    return wrapper


